/**
 * Excel adapter (wiki/design/excel-integration.md, E1–E5). The fourth adapter after Chart.js /
 * ECharts / React, and — like the ECharts one — it never imports its host: every Office.js
 * object it touches is typed STRUCTURALLY (`ExcelHostLike`, `WorksheetLike`, `RangeLike`), so
 * there is no `@types/office-js` dependency, the artifact's only external is the core, and the
 * live-sync logic is unit-testable against a fake host in Node.
 *
 * Two layers, deliberately split (E2):
 *
 *   1. `excelRangeToHangingStringsDiagram(values, options)` — a PURE mapper from a 2-D cell
 *      array (exactly what `Range.values` gives you) to the canonical shape (integration I3).
 *      Column roles are found by header name, else by position; a `parent` column nests rows
 *      into the D16 hierarchy. No Office.js, no DOM.
 *
 *   2. `attachHangingStringsDiagramToExcel(container, config)` — the host-side glue: resolves the
 *      source range (an explicit address, a table, or the worksheet's used range), reads it
 *      through `Excel.run`, mounts the façade, and keeps the chart in sync with the grid via
 *      `Worksheet.onChanged` (E4), with an optional value-diffing poll (`pollMs`) as the
 *      safety net for edits the event does not report. Refreshes never overlap (a change
 *      arriving mid-read queues one follow-up read), and `dispose()` removes the handler,
 *      stops the poll and destroys the chart.
 *
 * The content add-in page (addins/excel/) is a CONSUMER of this module, never part of it —
 * same litmus test the demo panel passes for the façade (I4).
 */

import {
  createHangingStringsDiagram,
  type HangingStringsDiagram,
  type HangingStringsDiagramOptions,
  type HangingStringCategory,
  type HangingStringGroup,
} from "hanging-strings-diagram";

// ---------------------------------------------------------------------------------------------
// 1. The pure mapper
// ---------------------------------------------------------------------------------------------

/** What `Excel.Range.values` holds per cell: numbers, text, booleans, or "" for empty cells
 * (Office.js reports blanks as empty strings; `null` is accepted too for callers building
 * arrays by hand). */
export type ExcelCellValue = string | number | boolean | null;

/** A column may be named by zero-based index or by its header text (case-insensitive). */
export type ExcelColumnRef = number | string;

export interface ExcelRangeMappingOptions {
  /** Whether row 0 is a header row. `"auto"` (default): it is, when the value column's first
   * cell is not numeric. */
  header?: boolean | "auto";
  /** Explicit column roles. Anything not given is resolved from header names, then position
   * (A = name, B = value, then C/D = secondary / group by cell type). */
  columns?: {
    name?: ExcelColumnRef;
    value?: ExcelColumnRef;
    secondary?: ExcelColumnRef;
    group?: ExcelColumnRef;
    parent?: ExcelColumnRef;
  };
  /** Declared groups win for names/colors; groups the sheet references but the caller did not
   * declare get palette colors, in first-seen order. Declared-but-unreferenced groups are kept
   * (stable legend contract, as in the other adapters). */
  groups?: HangingStringGroup[];
  /** Colors for undeclared groups, cycled. */
  palette?: string[];
}

export interface ExcelMappedData {
  categories: HangingStringCategory[];
  groups: HangingStringGroup[];
  /** Which zero-based columns were used for which role (for a host's status line). */
  columns: { name: number; value: number; secondary: number | null; group: number | null; parent: number | null };
  /** Whether row 0 was consumed as a header. */
  header: boolean;
}

/** Header aliases per role — matched case-insensitively against a trimmed header cell. */
const HEADER_ALIASES: Record<keyof NonNullable<ExcelRangeMappingOptions["columns"]>, string[]> = {
  name: ["name", "label", "category", "item", "kpi", "metric", "title"],
  value: ["value", "amount", "primary", "length", "score", "total", "count"],
  secondary: ["secondary", "second", "secondary value", "2nd", "knob", "heat", "weight", "share"],
  group: ["group", "series", "team", "segment", "type", "bucket"],
  parent: ["parent", "parent id", "belongs to", "under"],
};

/** The palette for undeclared groups: distinct, print-safe hues that read on the Studio and
 * Wool & brass grounds alike. Group color is a data encoding (deliberately not themable). */
export const DEFAULT_EXCEL_PALETTE = [
  "#3b6fd8",
  "#d9772d",
  "#2f9e63",
  "#c94a7a",
  "#7a5fd6",
  "#c9a227",
  "#2fa4b8",
  "#8b5e3c",
];

/** Implicit group id when the sheet has no group column — mirrors the other adapters. */
const IMPLICIT_GROUP_ID = "all";
const IMPLICIT_GROUP_NAME = "Values";

function isBlank(v: ExcelCellValue | undefined): boolean {
  return v === null || v === undefined || (typeof v === "string" && v.trim() === "");
}

function asNumber(v: ExcelCellValue | undefined): number | null {
  if (isBlank(v) || typeof v === "boolean") return null;
  const n = typeof v === "number" ? v : Number(String(v).replace(/[,\s%]/g, ""));
  return Number.isFinite(n) ? n : null;
}

function asText(v: ExcelCellValue | undefined): string {
  return isBlank(v) ? "" : String(v).trim();
}

function normalizeHeader(v: ExcelCellValue | undefined): string {
  return asText(v).toLowerCase().replace(/[_\-]+/g, " ").replace(/\s+/g, " ");
}

/** Slug used as a group id — stable across re-reads, safe as a CSS/DOM token. */
function slug(s: string): string {
  const out = s.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "");
  return out || "group";
}

function resolveColumn(
  ref: ExcelColumnRef | undefined,
  headers: string[] | null,
  width: number
): number | null {
  if (ref === undefined) return null;
  if (typeof ref === "number") return ref >= 0 && ref < width ? ref : null;
  if (!headers) return null;
  const wanted = normalizeHeader(ref);
  const i = headers.indexOf(wanted);
  return i === -1 ? null : i;
}

function findByAlias(role: keyof typeof HEADER_ALIASES, headers: string[] | null, taken: Set<number>): number | null {
  if (!headers) return null;
  for (const alias of HEADER_ALIASES[role]) {
    const i = headers.indexOf(alias);
    if (i !== -1 && !taken.has(i)) return i;
  }
  return null;
}

/** Fraction of non-blank cells in a column (over data rows) that parse as numbers. */
function numericShare(values: ExcelCellValue[][], col: number, fromRow: number): number {
  let seen = 0;
  let numeric = 0;
  for (let r = fromRow; r < values.length; r++) {
    const v = values[r]?.[col];
    if (isBlank(v)) continue;
    seen++;
    if (asNumber(v) !== null) numeric++;
  }
  return seen === 0 ? 0 : numeric / seen;
}

/**
 * Pure mapper: a 2-D cell array (`Range.values`) → the canonical Hanging Strings Diagram shape.
 *
 * Rules (E2): rows with a blank name or a non-numeric value are skipped (the sheet's own
 * "missing data" convention — a blank or a text note in the value cell); duplicate names get
 * a numeric suffix so ids stay unique; a `parent` column nests rows under the row whose name
 * matches (unknown parents fall back to top level); groups come from the group column (id =
 * slug of the text), else the single implicit group.
 */
export function excelRangeToHangingStringsDiagram(
  values: ExcelCellValue[][],
  options: ExcelRangeMappingOptions = {}
): ExcelMappedData {
  const width = values.reduce((w, row) => Math.max(w, row?.length ?? 0), 0);
  if (values.length === 0 || width === 0) {
    return {
      categories: [],
      groups: options.groups ? [...options.groups] : [],
      columns: { name: 0, value: 1, secondary: null, group: null, parent: null },
      header: false,
    };
  }

  // --- header detection -------------------------------------------------------------------
  const firstRowHeaders = (values[0] ?? []).map(normalizeHeader);
  const explicit = options.columns ?? {};
  const taken = new Set<number>();

  // Value column first: it decides "auto" header detection.
  let valueCol =
    resolveColumn(explicit.value, firstRowHeaders, width) ?? findByAlias("value", firstRowHeaders, taken);
  let nameCol =
    resolveColumn(explicit.name, firstRowHeaders, width) ?? findByAlias("name", firstRowHeaders, taken);

  let header: boolean;
  if (options.header === true || options.header === false) header = options.header;
  else {
    const probeCol = valueCol ?? (width > 1 ? 1 : 0);
    // Header when the first cell of the value column is not a number (a title like "Value"),
    // or when any known alias appears in row 0.
    const aliasHit = (Object.keys(HEADER_ALIASES) as (keyof typeof HEADER_ALIASES)[]).some((role) =>
      HEADER_ALIASES[role].some((a) => firstRowHeaders.includes(a))
    );
    header = aliasHit || asNumber(values[0]?.[probeCol]) === null;
  }
  const headers = header ? firstRowHeaders : null;
  const firstDataRow = header ? 1 : 0;

  // Re-resolve with the header decision made (aliases only count when there IS a header).
  valueCol = resolveColumn(explicit.value, headers, width) ?? findByAlias("value", headers, taken);
  if (valueCol !== null) taken.add(valueCol);
  nameCol = resolveColumn(explicit.name, headers, width) ?? findByAlias("name", headers, taken);
  if (nameCol !== null) taken.add(nameCol);

  // Positional fallbacks: name = first untaken text-ish column, value = first untaken numeric one.
  if (nameCol === null) {
    nameCol = [...Array(width).keys()].find((c) => !taken.has(c) && numericShare(values, c, firstDataRow) < 0.5) ?? 0;
    taken.add(nameCol);
  }
  if (valueCol === null) {
    valueCol =
      [...Array(width).keys()].find((c) => !taken.has(c) && numericShare(values, c, firstDataRow) >= 0.5) ??
      (width > 1 ? (nameCol === 1 ? 0 : 1) : 0);
    taken.add(valueCol);
  }

  let secondaryCol = resolveColumn(explicit.secondary, headers, width) ?? findByAlias("secondary", headers, taken);
  if (secondaryCol !== null) taken.add(secondaryCol);
  let groupCol = resolveColumn(explicit.group, headers, width) ?? findByAlias("group", headers, taken);
  if (groupCol !== null) taken.add(groupCol);
  let parentCol = resolveColumn(explicit.parent, headers, width) ?? findByAlias("parent", headers, taken);
  if (parentCol !== null) taken.add(parentCol);

  // Positional fallbacks for the optional roles (only when the sheet has no header to say):
  // the next numeric column is the 2nd metric, the next text column is the group.
  if (!headers) {
    for (let c = 0; c < width; c++) {
      if (taken.has(c)) continue;
      const share = numericShare(values, c, firstDataRow);
      if (secondaryCol === null && share >= 0.5) {
        secondaryCol = c;
        taken.add(c);
      } else if (groupCol === null && share < 0.5 && numericShare(values, c, firstDataRow) === 0) {
        groupCol = c;
        taken.add(c);
      }
    }
  }

  // --- rows → categories --------------------------------------------------------------------
  const declared = options.groups ?? [];
  const declaredById = new Map(declared.map((g) => [g.id, g]));
  const declaredByName = new Map(declared.map((g) => [g.name.toLowerCase(), g]));
  const palette = options.palette?.length ? options.palette : DEFAULT_EXCEL_PALETTE;

  const groups: HangingStringGroup[] = [];
  const groupIdFor = (raw: string): string => {
    const text = raw.trim();
    const known = declaredById.get(text) ?? declaredByName.get(text.toLowerCase());
    const id = known?.id ?? (text ? slug(text) : IMPLICIT_GROUP_ID);
    if (!groups.some((g) => g.id === id)) {
      groups.push(
        known ?? {
          id,
          name: text || IMPLICIT_GROUP_NAME,
          color: palette[groups.length % palette.length],
        }
      );
    }
    return id;
  };

  const usedIds = new Set<string>();
  const uniqueId = (name: string): string => {
    let id = name;
    for (let n = 2; usedIds.has(id); n++) id = `${name} (${n})`;
    usedIds.add(id);
    return id;
  };

  interface Row {
    cat: HangingStringCategory;
    parentName: string;
  }
  const rows: Row[] = [];
  for (let r = firstDataRow; r < values.length; r++) {
    const row = values[r] ?? [];
    const name = asText(row[nameCol]);
    const value = asNumber(row[valueCol]);
    if (!name || value === null) continue;
    const groupId = groupCol === null ? groupIdFor("") : groupIdFor(asText(row[groupCol]));
    const secondary = secondaryCol === null ? null : asNumber(row[secondaryCol]);
    const cat: HangingStringCategory = {
      id: uniqueId(name),
      name,
      groupId,
      value,
      ...(secondary !== null ? { secondaryValue: secondary } : {}),
    };
    rows.push({ cat, parentName: parentCol === null ? "" : asText(row[parentCol]) });
  }

  // --- hierarchy (D16): nest under the first row whose NAME matches the parent cell -------
  const byName = new Map<string, HangingStringCategory>();
  for (const { cat } of rows) if (!byName.has(cat.name)) byName.set(cat.name, cat);
  const categories: HangingStringCategory[] = [];
  for (const { cat, parentName } of rows) {
    const parent = parentName ? byName.get(parentName) : undefined;
    if (parent && parent !== cat && !isDescendant(cat, parent)) {
      (parent.children ??= []).push(cat);
    } else {
      categories.push(cat);
    }
  }

  // Declared groups the sheet never referenced stay in the legend.
  for (const g of declared) if (!groups.some((x) => x.id === g.id)) groups.push(g);

  return {
    categories,
    groups,
    columns: { name: nameCol, value: valueCol, secondary: secondaryCol, group: groupCol, parent: parentCol },
    header,
  };
}

/** True when `maybeAncestor` already sits inside `node`'s subtree (guards a→b→a cycles). */
function isDescendant(node: HangingStringCategory, maybeAncestor: HangingStringCategory): boolean {
  for (const child of node.children ?? []) {
    if (child === maybeAncestor || isDescendant(child, maybeAncestor)) return true;
  }
  return false;
}

// ---------------------------------------------------------------------------------------------
// 2. The host glue — structural Office.js types
// ---------------------------------------------------------------------------------------------

/** The slice of `Excel.Range` the adapter reads. Real proxies expose far more; a test fake
 * needs only this. */
export interface RangeLike {
  address: string;
  values: ExcelCellValue[][];
  load(properties: string): unknown;
}

export interface WorksheetChangedArgsLike {
  address: string;
  changeType?: string;
  worksheetId?: string;
}

export interface EventHandlerResultLike {
  remove(): unknown;
}

export interface WorksheetLike {
  name: string;
  load(properties: string): unknown;
  getRange(address: string): RangeLike;
  getUsedRange(valuesOnly?: boolean): RangeLike;
  /** Absent on hosts below ExcelApi 1.7 — the adapter then degrades to manual `refresh()`. */
  onChanged?: {
    add(handler: (args: WorksheetChangedArgsLike) => Promise<unknown> | unknown): EventHandlerResultLike;
  };
}

export interface TableLike {
  getRange(): RangeLike;
  getWorksheet(): WorksheetLike;
}

export interface WorkbookLike {
  worksheets: {
    getActiveWorksheet(): WorksheetLike;
    getItem(name: string): WorksheetLike;
  };
  tables?: {
    getItem(name: string): TableLike;
  };
}

export interface ExcelContextLike {
  workbook: WorkbookLike;
  sync(): Promise<unknown>;
}

/** `Excel` (the Office.js namespace object) satisfies this: `Excel.run(batch)`. */
export interface ExcelHostLike {
  run<T>(batch: (context: ExcelContextLike) => Promise<T>): Promise<T>;
}

/** Where the chart's data lives. Precedence: `table` > `address` > the used range of
 * `worksheet` (or the active worksheet). */
export interface ExcelDataSource {
  /** Worksheet name; default: the active worksheet at attach time. */
  worksheet?: string;
  /** A1-style address (with or without a sheet prefix); default: the worksheet's used range,
   * re-measured on every refresh so appended rows appear. */
  address?: string;
  /** A table name (structured reference). Its worksheet wins over `worksheet`. */
  table?: string;
}

export interface ExcelSyncMeta {
  worksheet: string;
  address: string;
  mapped: ExcelMappedData;
  /** What triggered the read: initial mount, an explicit refresh(), a `Worksheet.onChanged`
   * event, or the polling fallback noticing different cell values. */
  reason: "mount" | "refresh" | "change" | "poll";
}

export interface HangingStringsDiagramExcelConfig
  extends Omit<Partial<HangingStringsDiagramOptions>, "categories" | "groups"> {
  /** The Office.js `Excel` namespace (or any structural stand-in). */
  excel: ExcelHostLike;
  source?: ExcelDataSource;
  mapping?: ExcelRangeMappingOptions;
  /** Follow `Worksheet.onChanged` (default true). Off = manual `refresh()` only. */
  live?: boolean;
  /** Safety net for edits `onChanged` does not report (automation/AppleScript/VBA writes,
   * hosts below ExcelApi 1.7): re-read every `pollMs` ms and update only when the cell
   * values differ. 0 (default) = off. Coalesces with the event path — a poll never runs
   * while a read is in flight. */
  pollMs?: number;
  /** Declared groups (colors/names) — sugar for `mapping.groups`. */
  groups?: HangingStringGroup[];
  /** Fires after every successful read (mount, refresh, change) with what was read. */
  onSync?: (meta: ExcelSyncMeta) => void;
  /** Fires when a read fails (e.g. the source range was deleted). The chart keeps its last
   * good data. */
  onError?: (error: unknown) => void;
  /** Test seam / custom façade: how the chart instance is created. Default: the real façade. */
  createDiagram?: typeof createHangingStringsDiagram;
}

export interface HangingStringsDiagramExcel {
  /** The underlying façade instance — the public surface for look/behavior changes. */
  readonly instance: HangingStringsDiagram;
  /** Where the last successful read came from. */
  readonly source: { worksheet: string; address: string };
  /** True while a `Worksheet.onChanged` handler is bound (false on hosts without the event,
   * or with `live: false`). */
  readonly live: boolean;
  /** Re-read the source range and update the chart. Concurrent calls coalesce. */
  refresh(): Promise<void>;
  /** Point the chart at a different range/table (re-reads immediately, re-binds live sync). */
  setSource(source: ExcelDataSource): Promise<void>;
  /** Removes the change handler and destroys the chart. Safe to call more than once. */
  dispose(): Promise<void>;
}

/** Reads the source range inside one `Excel.run` batch. Exported for tests and for hosts that
 * only want the data. */
export async function readExcelSource(
  excel: ExcelHostLike,
  source: ExcelDataSource = {}
): Promise<{ worksheet: string; address: string; values: ExcelCellValue[][] }> {
  return excel.run(async (ctx) => {
    let sheet: WorksheetLike;
    let range: RangeLike;
    if (source.table) {
      const tables = ctx.workbook.tables;
      if (!tables) throw new Error("This host exposes no workbook.tables");
      const table = tables.getItem(source.table);
      sheet = table.getWorksheet();
      range = table.getRange();
    } else {
      sheet = source.worksheet
        ? ctx.workbook.worksheets.getItem(source.worksheet)
        : ctx.workbook.worksheets.getActiveWorksheet();
      range = source.address ? sheet.getRange(source.address) : sheet.getUsedRange(true);
    }
    sheet.load("name");
    range.load("address,values");
    await ctx.sync();
    return { worksheet: sheet.name, address: range.address, values: range.values ?? [] };
  });
}

/**
 * Mounts the façade in `container`, seeded from the Excel source, and keeps it in sync with
 * the grid. Resolves once the first read has rendered (rejects if that read fails — a host
 * bug like a wrong address should fail loudly, per the façade's own convention).
 */
export async function attachHangingStringsDiagramToExcel(
  container: HTMLElement,
  config: HangingStringsDiagramExcelConfig
): Promise<HangingStringsDiagramExcel> {
  const { excel, mapping, live = true, pollMs = 0, onSync, onError, createDiagram, groups, ...display } = config;
  const mappingOptions: ExcelRangeMappingOptions = { ...mapping, groups: mapping?.groups ?? groups };
  const create = createDiagram ?? createHangingStringsDiagram;

  let source: ExcelDataSource = config.source ?? {};
  let current = { worksheet: "", address: "" };
  let disposed = false;
  let handler: EventHandlerResultLike | null = null;
  let inflight: Promise<void> | null = null;
  let queued = false;

  const first = await readExcelSource(excel, source);
  let mapped = excelRangeToHangingStringsDiagram(first.values, mappingOptions);
  current = { worksheet: first.worksheet, address: first.address };
  /** Fingerprint of the last applied read — a poll that sees the same cells does nothing. */
  let lastSeen = JSON.stringify([first.address, first.values]);
  const instance = create(container, { ...display, categories: mapped.categories, groups: mapped.groups });
  onSync?.({ ...current, mapped, reason: "mount" });

  const readAndApply = async (reason: ExcelSyncMeta["reason"]): Promise<void> => {
    if (disposed) return;
    try {
      const read = await readExcelSource(excel, source);
      if (disposed) return;
      const seen = JSON.stringify([read.address, read.values]);
      if (reason === "poll" && seen === lastSeen) return;
      lastSeen = seen;
      mapped = excelRangeToHangingStringsDiagram(read.values, mappingOptions);
      current = { worksheet: read.worksheet, address: read.address };
      instance.update({ categories: mapped.categories, groups: mapped.groups });
      onSync?.({ ...current, mapped, reason });
    } catch (err) {
      if (onError) onError(err);
      else throw err;
    }
  };

  /** Coalescing refresh: at most one read in flight, at most one queued behind it. A poll
   * that finds a read in flight simply skips — the in-flight read already sees the cells. */
  const refresh = (reason: ExcelSyncMeta["reason"]): Promise<void> => {
    if (inflight) {
      if (reason !== "poll") queued = true;
      return inflight;
    }
    inflight = (async () => {
      do {
        queued = false;
        await readAndApply(reason);
        reason = "change";
      } while (queued && !disposed);
    })().finally(() => {
      inflight = null;
    });
    return inflight;
  };

  const bindLive = async (): Promise<void> => {
    await unbindLive();
    if (!live || disposed) return;
    await excel.run(async (ctx) => {
      const sheet = source.table
        ? ctx.workbook.tables?.getItem(source.table).getWorksheet()
        : source.worksheet
          ? ctx.workbook.worksheets.getItem(source.worksheet)
          : ctx.workbook.worksheets.getActiveWorksheet();
      if (!sheet?.onChanged) return; // host below ExcelApi 1.7: manual refresh() only
      handler = sheet.onChanged.add(() => refresh("change"));
      await ctx.sync();
    });
  };

  const unbindLive = async (): Promise<void> => {
    const h = handler;
    handler = null;
    if (!h) return;
    try {
      await excel.run(async (ctx) => {
        h.remove();
        await ctx.sync();
      });
    } catch (err) {
      onError?.(err);
    }
  };

  await bindLive();

  const pollTimer =
    pollMs > 0
      ? setInterval(() => {
          void refresh("poll");
        }, pollMs)
      : null;

  return {
    instance,
    get source() {
      return current;
    },
    get live() {
      return handler !== null;
    },
    refresh: () => refresh("refresh"),
    async setSource(next) {
      source = next;
      await refresh("refresh");
      await bindLive();
    },
    async dispose() {
      if (disposed) return;
      disposed = true;
      if (pollTimer) clearInterval(pollTimer);
      await unbindLive();
      instance.destroy();
    },
  };
}
